function resolveInputFile(inputPath) {
  const resolved = path.resolve(inputPath);
  if (!fs.existsSync(resolved)) {
    console.error(`Error: Path not found: ${resolved}`);
    process.exit(1); // hard-fail on a bad path rather than continuing with nothing to parse
  }
  const stat = fs.statSync(resolved);
  if (!stat.isDirectory()) return resolved; // it's a file, use directly

  // Scan folder for .xlsx files (non-temp, non-hidden)
  const files = fs.readdirSync(resolved)
    .filter(f => f.endsWith('.xlsx') && !f.startsWith('~$') && !f.startsWith('.')) // '~$' is Excel's lock file for a workbook still open in the app — parsing it would throw; dotfiles are hidden/OS cruft
    .map(f => {
      const full = path.join(resolved, f);
      return { name: f, path: full, mtime: fs.statSync(full).mtimeMs }; // mtimeMs is the recency key — filenames aren't reliably ordered
    })
    .sort((a, b) => b.mtime - a.mtime); // newest first

  if (files.length === 0) {
    console.error(`Error: No .xlsx files found in ${resolved}`);
    process.exit(1);
  }
  return files[0].path;
}

function detectWideFormat(rows) {
  if (rows.length < 3) return null; // need header + note row + at least one data row; anything shorter can't be a real sheet
  const row2 = rows[1]; // the NOTE row — where 'Tester #N: Name' banners live in a shared workbook
  const testerBlocks = [];

  for (let c = 0; c < (row2?.length || 0); c++) {
    const val = String(row2[c] || '').trim(); // coerce: cells may be numbers, undefined, or missing — String()||'' guards all three before matching
    const match = val.match(/^Tester\s*#?\s*(\d+)\s*:\s*(.*)/i); // tolerant pattern: optional '#', flexible spacing, case-insensitive — testers type these headers inconsistently
    if (match) {
      const name = match[2].trim() || `Tester #${match[1]}`; // fall back to the numbered label when someone left the name blank after the colon
      testerBlocks.push({ testerName: name, colOffset: c }); // colOffset marks where this tester's column block starts — used later to slice their answers out of the wide row
    }
  }
  return testerBlocks.length > 1 ? testerBlocks : null; // >1 = genuinely wide/shared; 0 or 1 banner means a normal single-tester sheet, signalled by null
}

