  const sampleResults = results.filter(r => r.sheet === 'Sample Prompts');
  const samplePassed = sampleResults.filter(r => r.passFail === 'Pass'); // exact 'Pass' only — blank/untested rows fall through both buckets and don't inflate either count
  const sampleFailed = sampleResults.filter(r => r.passFail === 'Fail');
  // ... same tally repeated for the New Prompts sheet, then combined ...

  const passRate = totalTested > 0 ? (totalPassed / totalTested) * 100 : 0; // guard divide-by-zero: an all-untested round reports 0%, not NaN

  const exitCriteria = {
    // coverage passes only if every unique test number was passed by at least one tester — a Set comparison, so a prompt tried by 3 testers still counts once
    testCoverage: uniqueTestNums.size > 0 && passedTestNums.size >= uniqueTestNums.size,
    passRate: passRate >= 80, // fixed 80% launch bar
    criticalIssues: highIssues === 0, // zero high-severity issues, not 'few'
    formalSignOff: false, // always pending — a human decision, never auto-satisfied by the numbers
  };

  return { totalPrompts, totalTested, coveragePct, passRate, exitCriteria /* ...more */ };
}

function classifyIssues(failedResults) {
  return failedResults.map(r => ({
    testNum: r.testNum,
    feature: r.feature,
    classification: r.classification || r.feature || 'Other', // cascade: explicit bucket, else group by feature area, else 'Other' — every failure lands in some named bucket
    comment: r.testerComments || r.actualResults || '(no comment)', // prefer the tester's own note; fall back to the observed result; last resort a placeholder so the field is never empty
    tester: r.tester,
  }));
}

async function generatePptx(metrics, outputPath, linkedFiles) {
  const PptxGenJS = (await import('pptxgenjs')).default; // dynamic import: the heavy slide lib loads only when actually rendering, so --dry-run never pays for it
  const pptx = new PptxGenJS();
  pptx.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches — 16:9, the projector aspect ratio for the go/no-go room

  const slide = pptx.addSlide();
  slide.addShape('rect', { x: 0, y: 0, w: '100%', h: 0.55, fill: { color: TEAL } }); // header band; coordinates are in INCHES, w:'100%' spans the full slide width
  slide.addText([
    // one addText with two runs so 'UAT Summary' is bold and the date is lighter within a single text box, kept on one baseline
    { text: 'UAT Summary', options: { fontSize: 14, bold: true, color: WHITE } },
    { text: `  |  ${dateStr}`, options: { fontSize: 11, color: WHITE } },
  ], { x: 0.3, y: 0.1, w: 9, h: 0.35 });

  // ... draws the coverage/pass-rate rings, the sample/new prompt
  // metric cards, the issue bars, and the exit-criteria bar ...

  await pptx.writeFile({ fileName: outputPath }); // async write — the whole function is awaited so callers know the .pptx is flushed before continuing
}
